files.tally.sh:
#!/bin/sh
# Total the sightings per species in a notes file.
# Usage: sh tally.sh NOTES_FILE
file="$1"
[ -r "$file" ] || { echo "cannot read notes file" >&2; exit 2; }
awk '
  { total[$2] += $3 }
  END { for (s in total) printf "%d %s\n", total[s], s }
' "$file" | sort -k2

files.check.sh:
#!/bin/sh
# Tally the spring notes and compare with the expected totals.
sh tally.sh notes/2026-spring.txt | diff - expected-spring.txt && echo "spring ok"
